using System;
using System.IO;
using System.Collections;
using UnityEngine;
using HarborValeGreybox.Racing;
namespace HarborValeGreybox.SportsTest {
public class ApexPlayerProbe:MonoBehaviour {
 string folder;string[] files;string[] before;bool error;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--sports-smoke-dir");if(Debug.isDebugBuild&&i>=0&&i+1<args.Length){var probe=new GameObject("Sports Windows verification").AddComponent<ApexPlayerProbe>();probe.folder=Path.GetFullPath(args[i+1]);}}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception){error=true;}}
 void Check(bool value,string reason){if(!value)throw new Exception(reason);}
 IEnumerator Start(){Directory.CreateDirectory(folder);files=new[]{DocksideTrialDirector.SavePath,DocksideTrialDirector.LegacySavePath,DocksideTrialDirector.OlderSavePath};before=new string[3];for(int i=0;i<3;i++)before[i]=File.Exists(files[i])?File.ReadAllText(files[i]):null;ApexTestDrive test=null;float until=Time.realtimeSinceStartup+30;while((test=UnityEngine.Object.FindAnyObjectByType<ApexTestDrive>())==null||!test.Ready){if(Time.realtimeSinceStartup>until){File.WriteAllText(Path.Combine(folder,"player-smoke.txt"),"FAIL startup timeout");Application.Quit(1);yield break;}yield return null;}yield return new WaitForSecondsRealtime(1);
  Check(UnityEngine.Object.FindAnyObjectByType<DocksideTrialDirector>()==null,"Sports scene started career trial");Check(!test.SelectStep(3),"Turbo skipped prerequisites");Check(test.SelectStep(1)&&test.SelectStep(2)&&test.SelectStep(3)&&test.SelectStep(4),"Sequential test upgrades failed");Check(test.Car.Engine.definition.SampleTorque(4500)==510,"Street cooler curve missing");yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,"Sports_Upgrades.png"));yield return new WaitForSecondsRealtime(.4f);
  var chase=Camera.main.GetComponent<HarborValeGreybox.Driving.FinchChaseCamera>();chase.enabled=false;Camera.main.transform.position=test.Car.transform.TransformPoint(new Vector3(-5,2.7f,6));Camera.main.transform.LookAt(test.Car.transform.position+Vector3.up*.7f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,"Sports_Model.png"));yield return new WaitForSecondsRealtime(.4f);chase.enabled=true;chase.Snap();test.Car.externalInput=true;test.Car.commandedPedal=1;yield return new WaitForSecondsRealtime(3);Check(test.Car.SpeedKph>30&&test.Car.Engine.TurboAvailability>0,"Sports car did not drive/spool");Check(!test.SelectStep(0),"Moving car permitted hardware replacement");yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,"Sports_Driving.png"));yield return new WaitForSecondsRealtime(.4f);test.Car.Recover();Check(test.Step==4&&test.Car.Engine.definition.SampleTorque(4500)==510&&test.Car.Engine.TurboAvailability==0,"Recovery lost configuration");for(int i=0;i<3;i++)Check(before[i]==(File.Exists(files[i])?File.ReadAllText(files[i]):null),"Career save changed");Check(!error,"Runtime error logged");File.WriteAllText(Path.Combine(folder,"player-smoke.txt"),"PASS Windows sports scene: sequential upgrades, no skips, moving install rejection, 510 Nm installed, loaded driving/spool, recovery persistence, rendered model/UI and unchanged career save files. No trial instantiated.\n");Application.Quit(0);
 }
}
}
